/// <summary>
/// TAMRebateDealSubmitManager extension class
/// </summary>
[ExtensionOf(classStr(TAMRebateDealSubmitManager))]
final class METTAMRebateDealSubmitManager_Extension
{
}

Method.Source:
/// <summary>
/// Rebate deal workflow submit manager checks for rate and value type rebate lines if the deal is of type volumetric rebate
/// </summary>
/// <param name = "_args">Args instance</param>
public static void main(Args _args)
{
    RefRecId tamRebateDealRecId = _args.record().RecId;

    if (TAMRebateDeal::find(tamRebateDealRecId).METVolumetricTierDeal)
    {
        if (!TAMRebateTable::existByTierType(tamRebateDealRecId, METTierLineType::Rate) 
            || !TAMRebateTable::existByTierType(tamRebateDealRecId, METTierLineType::Value))
        {
            throw error("@MET:VolRebateWorkFlowErrorMessage");
        }
    }

    next main(_args);
}
